     */
    bytes32 public constant NO_SIGNAL = keccak256("NO_SIGNAL");

    /// @notice Subgraph signal below minimumSubgraphSignal threshold
    bytes32 public constant BELOW_MINIMUM_SIGNAL = keccak256("BELOW_MINIMUM_SIGNAL");

