        require(_isValid(wrapper), IndexingAgreementNotActive(rcau.agreementId));
        require(
            wrapper.collectorAgreement.serviceProvider == indexer,
            IndexingAgreementNotAuthorized(rcau.agreementId, indexer)
        );

