        (bool isCollectable, uint256 collectionSeconds, ) = _directory().recurringCollector().getCollectionInfo(
            params.agreementId
        );
        require(_isValid(wrapper) && isCollectable, IndexingAgreementNotCollectable(params.agreementId));

